+package com.example.contact;
+
+import java.util.ArrayDeque;
+import java.util.Deque;
+import java.util.List;
+
+import org.springframework.stereotype.Service;
+
+/**
+ * Keeps the sent messages in memory for the lifetime of the application, so
+ * the list survives navigating away from the contact view.
+ */
+@Service
+public class ContactMessageService {
+
+    private final Deque<ContactMessage> messages = new ArrayDeque<>();
+
+    public synchronized void add(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    /**
+     * @return all sent messages, newest first
+     */
+    public synchronized List<ContactMessage> getMessages() {
+        return List.copyOf(messages);
+    }
+}
