+package com.example.contact;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.HasValidation;
+import com.vaadin.flow.component.HasValue;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.Shortcuts;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.button.ButtonVariant;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
+
+    private final ContactMessageService messages;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<ContactMessage> grid = new Grid<>(ContactMessage.class, false);
+
+    private final Dialog leaveDialog = new Dialog();
+    private BeforeLeaveEvent.ContinueNavigationAction pendingNavigation;
+
+    public ContactView(ContactMessageService messages) {
+        this.messages = messages;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message);
+        form.setColspan(message, 2);
+
+        // EAGER so that Send is re-enabled on every keystroke, not on blur.
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+        for (var field : new HasValue<?, ?>[] { name, email, phone, message }) {
+            field.addValueChangeListener(e -> send.setEnabled(true));
+        }
+
+        send.addClickListener(e -> submit());
+
+        // Enter sends from any input field; Shift+Enter is left alone so the
+        // message can still be written over several lines.
+        Shortcuts.addShortcutListener(this, this::submit, Key.ENTER);
+
+        grid.addColumn(ContactMessage::name).setHeader("Name").setAutoWidth(true);
+        grid.addColumn(ContactMessage::email).setHeader("Email").setAutoWidth(true);
+        grid.addColumn(ContactMessage::phone).setHeader("Phone").setAutoWidth(true);
+        grid.addColumn(ContactMessage::message).setHeader("Message").setFlexGrow(1);
+        grid.setAllRowsVisible(true);
+        refreshGrid();
+
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph("The form has unsent input. Leaving will throw it away."));
+        Button keepEditing = new Button("Keep editing", e -> {
+            BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+            closeLeaveDialog();
+            if (action != null) {
+                // Ends the postponed navigation so the next attempt is asked about again.
+                action.cancel();
+            }
+        });
+        Button discard = new Button("Discard", e -> {
+            BeforeLeaveEvent.ContinueNavigationAction action = pendingNavigation;
+            closeLeaveDialog();
+            if (action != null) {
+                action.proceed();
+            }
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        leaveDialog.getFooter().add(new HorizontalLayout(keepEditing, discard));
+        // Only the two buttons may answer the question, so the navigation is never
+        // left hanging by an Esc or an outside click.
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+
+        add(form, send, grid, leaveDialog);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasInput()) {
+            pendingNavigation = event.postpone();
+            leaveDialog.open();
+        }
+    }
+
+    private boolean hasInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+
+    private void closeLeaveDialog() {
+        pendingNavigation = null;
+        leaveDialog.close();
+    }
+
+    private void submit() {
+        if (!send.isEnabled() || !validate()) {
+            return;
+        }
+
+        messages.add(new ContactMessage(
+                name.getValue().trim(),
+                email.getValue().trim(),
+                phone.getValue().trim(),
+                message.getValue()));
+
+        Notification.show("Message sent");
+
+        // Clearing fires value change events, which would re-enable Send.
+        // Disable it after clearing so the post-send state wins.
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        send.setEnabled(false);
+
+        refreshGrid();
+    }
+
+    private boolean validate() {
+        for (HasValidation field : new HasValidation[] { name, email, message }) {
+            field.setInvalid(false);
+        }
+
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            reject(name, "Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty()) {
+            if (!EMAIL.matcher(emailValue).matches()) {
+                reject(email, "Enter a valid e-mail address");
+                valid = false;
+            }
+        } else if (phoneValue.isEmpty()) {
+            reject(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String messageValue = message.getValue();
+        if (messageValue.isBlank()) {
+            reject(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            reject(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private static void reject(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messages.getMessages());
+    }
+}
