+package com.example.contact;
+
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Value;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.context.SpringBootTest.WebEnvironment;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+
+import com.microsoft.playwright.Page;
+import com.microsoft.playwright.options.AriaRole;
+
+@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserIT extends AbstractBasePlaywrightIT {
+
+    @Value("${local.server.port}")
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port + "/contact";
+    }
+
+    private Page.GetByRoleOptions sendButton() {
+        return new Page.GetByRoleOptions().setName("Send");
+    }
+
+    @Test
+    void emptySubmitShowsErrorsAndSendsNothing() throws Exception {
+        setupTest();
+        page.navigate(getUrl());
+
+        page.getByRole(AriaRole.BUTTON, sendButton()).click();
+
+        assertThat(page.getByText("Name is required")).isVisible();
+        assertThat(page.getByText("Message is required")).isVisible();
+        assertThat(page.getByText("Message sent")).not().isVisible();
+    }
+
+    @Test
+    void phoneOnlyMessageIsSentWithEnterAndListed() throws Exception {
+        setupTest();
+        page.navigate(getUrl());
+
+        page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Browser Person");
+        page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("+358 40 000");
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Hello from a browser");
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertThat(page.locator("vaadin-grid").getByText("Hello from a browser")).isVisible();
+        assertThat(page.getByRole(AriaRole.BUTTON, sendButton())).isDisabled();
+    }
+
+    @Test
+    void leavingWithInputAsksBeforeNavigating() throws Exception {
+        setupTest();
+        page.navigate(getUrl());
+
+        page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Do not lose me");
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+
+        DialogElement dialog = DialogElement.getByHeaderText(page, "Discard your message?");
+        dialog.assertOpen();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Keep editing")).click();
+        dialog.assertClosed();
+        assertThat(page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true))).hasValue("Do not lose me");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("About")).click();
+        page.getByRole(AriaRole.BUTTON, new Page.GetByRoleOptions().setName("Discard")).click();
+        assertThat(page.getByRole(AriaRole.HEADING, new Page.GetByRoleOptions().setName("About"))).isVisible();
+    }
+}
