+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name() {
+        return $(TextField.class).withCaption("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withCaption("Phone").single();
+    }
+
+    private TextArea message() {
+        return $(TextArea.class).single();
+    }
+
+    private Button send() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<ContactMessage> grid() {
+        return (Grid<ContactMessage>) $(Grid.class).single();
+    }
+
+    @Test
+    void contactViewShowsHeadingAndEmptyFormWithEnabledSend() {
+        navigate(ContactView.class);
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void aboutLinkNavigatesToAboutView() {
+        navigate(ContactView.class);
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptySubmitMarksRequiredFieldsAndSendsNothing() {
+        navigate(ContactView.class);
+        int before = grid().getGenericDataView().getItems().toList().size();
+
+        test(send()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(message().isInvalid());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertFalse(phone().isInvalid());
+        assertEquals(0, $(Notification.class).all().size());
+        assertEquals(before, grid().getGenericDataView().getItems().toList().size());
+    }
+
+    @Test
+    void invalidEmailIsReportedAndFormIsKept() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(email()).setValue("not-an-address");
+        test(message()).setValue("Hello");
+
+        test(send()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertEquals("Ada", name().getValue());
+        assertEquals("Hello", message().getValue());
+    }
+
+    @Test
+    void messageLongerThan500CharactersIsRejected() {
+        navigate(ContactView.class);
+        test(name()).setValue("Ada");
+        test(phone()).setValue("123");
+        test(message()).setValue("x".repeat(501));
+
+        test(send()).click();
+
+        assertTrue(message().isInvalid());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughAndMessageIsSentAndListed() {
+        navigate(ContactView.class);
+        test(name()).setValue("Phone Person");
+        test(phone()).setValue("+358 40 1234567");
+        test(message()).setValue("Call me");
+
+        test(send()).click();
+
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+        assertEquals("", name().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertFalse(send().isEnabled());
+
+        ContactMessage first = grid().getGenericDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Phone Person", first.name());
+        assertEquals("Call me", first.message());
+    }
+
+    @Test
+    void enterSendsTheMessage() {
+        navigate(ContactView.class);
+        test(name()).setValue("Enter Person");
+        test(phone()).setValue("555");
+        test(message()).setValue("Sent with Enter");
+
+        fireShortcut(Key.ENTER);
+
+        ContactMessage first = grid().getGenericDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Sent with Enter", first.message());
+    }
+
+    @Test
+    void editingAfterSendReEnablesSend() {
+        navigate(ContactView.class);
+        test(name()).setValue("Editor");
+        test(email()).setValue("editor@example.com");
+        test(message()).setValue("Hi");
+        test(send()).click();
+        assertFalse(send().isEnabled());
+
+        test(name()).setValue("Editor again");
+
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void sentMessagesSurviveLeavingTheView() {
+        navigate(ContactView.class);
+        test(name()).setValue("Persistent");
+        test(email()).setValue("persist@example.com");
+        test(message()).setValue("Remember me");
+        test(send()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        ContactMessage first = grid().getGenericDataView().getItems().findFirst().orElseThrow();
+        assertEquals("Persistent", first.name());
+        assertEquals("Remember me", first.message());
+    }
+
+    @Test
+    void leavingWithInputAsksFirstAndKeepEditingStaysPut() {
+        navigate(ContactView.class);
+        test(message()).setValue("Unsent words");
+
+        // Navigation is postponed by the view, so the UI call is used rather than navigate(),
+        // which expects the navigation to complete.
+        UI.getCurrent().navigate(AboutView.class);
+
+        Dialog dialog = $(Dialog.class).single();
+        assertTrue(dialog.isOpened());
+        assertTrue(getCurrentView() instanceof ContactView);
+        test($(Button.class).withText("Keep editing").single()).click();
+        assertFalse(dialog.isOpened());
+        assertEquals("Unsent words", message().getValue());
+
+        // Leaving again is asked about again, not silently ignored.
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue(dialog.isOpened());
+    }
+
+    @Test
+    void discardLeavesTheView() {
+        navigate(ContactView.class);
+        test(message()).setValue("Throw me away");
+
+        UI.getCurrent().navigate(AboutView.class);
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertEquals("About", $(H1.class).single().getText());
+    }
+}
